const QUESTOES_PT = [
  qCE(1, "Compreensão vs interpretação", "Compreender um texto, na linha da aula, é localizar o que está dito de forma explícita; interpretar é ir além do literal, colhendo o que se infere das relações entre as ideias.", 0, "Noslen separa os dois gestos: compreensão fica no escrito; interpretação lê as entrelinhas, sempre amparada no texto."),
  qCE(2, "Compreensão vs interpretação", "Em prova, compreensão e interpretação são operações idênticas: ambas autorizam completar o que o autor calou com palpite pessoal.", 1, "A aula recusa essa fusão. Compreensão cobra o explícito; interpretação cobra inferência textual, não chute."),
  qCE(3, "De acordo com o texto", "O comando 'de acordo com o texto' ou 'segundo o autor' amarra a resposta ao que o trecho efetivamente afirma, e não ao que o candidato acha razoável.", 0, "Noslen alerta: esse comando trava a leitura no escrito. Conhecimento de mundo não substitui o parágrafo."),
  qCE(4, "De acordo com o texto", "Quando a Quadrix ou a Cebraspe escreve 'de acordo com o texto', vale usar notícia de jornal vista na véspera para 'completar' o raciocínio do autor.", 1, "A aula é taxativa: 'de acordo com o texto' exclui dado externo. Se não está no texto, o item não pode ser dado como dito."),
  qCE(5, "Inferência", "Inferir é extrair conclusão sustentada pelo que o texto mostra — tom, conectivos, omissões relevantes — ainda que a frase da alternativa não copie o original.", 0, "Interpretação, na aula, é inferência controlada: o sentido está no texto, não na ficha do candidato."),
  qCE(6, "Inferência", "Toda inferência de prova é livre: se o texto fala de fila no posto, pode-se afirmar que o prefeito desviou verba, porque 'é o que sempre acontece'.", 1, "Isso é superinterpretação. A aula pede inferência ancorada, não romance policial sobre o autor."),
  qCE(7, "Detalhe (não/apenas/sempre)", "Em item Cebraspe, palavras como 'não', 'apenas', 'somente', 'sempre', 'nunca' e 'todas' costumam ser o gatilho que torna o enunciado falso.", 0, "Noslen e o treino de banca coincidem: o detalhe absoluto vira pegadinha. Leia o item palavra por palavra."),
  qCE(8, "Título e conclusão", "O título de um artigo dissertativo pode ser puramente ornamental: em prova, quase nunca dialoga com o tema nem com a tese.", 1, "A aula manda olhar título e fecho. Em dissertação, os dois costumam condensar o assunto e a conclusão."),
  qCE(9, "Título e conclusão", "Num texto dissertativo, o último parágrafo frequentemente retoma ou sintetiza a tese; por isso a conclusão ajuda a fechar o tema da questão.", 0, "Noslen recomenda mapear começo e fim antes de caçar detalhe no meio. A síntese final costuma ser o 'esqueleto' da tese."),
  qCE(10, "Conectivos", "Conectivos como 'mas', 'embora', 'portanto' e 'pois' não são enfeite: eles marcam oposição, concessão, conclusão ou causa entre orações.", 0, "A aula de interpretação trata coesão como mapa lógico. Trocar o conectivo troca a relação e, em banca, zera o item."),
  qCE(11, "Conectivos", "O conectivo 'embora' introduz ideia aditiva do mesmo teor de 'e' ou 'também', sem matiz concessivo.", 1, "Na aula, 'embora' é concessão (admite um fato e mantém o outro). Adição é 'e', 'além disso', 'também'."),
  qCE(12, "Tipologia", "A narração organiza fatos em eixo temporal, com personagens, espaço e enredo; a dissertação organiza tese e argumentos em torno de um ponto de vista.", 0, "Noslen separa os tipos para a prova não misturar 'o que aconteceu' com 'o que se defende'."),
  qCE(13, "Tipologia", "Todo texto de concurso é narração: mesmo o artigo de opinião deve ser lido como história de personagens, nunca como defesa de tese.", 1, "Dissertação-argumentação é o tipo mais cobrado em prova. Tratar editorial como conto é erro de tipologia da aula."),
  qCE(14, "Reescrita", "Reescrever trecho 'sem alteração de sentido' exige preservar relações lógicas (causa, oposição, tempo), não só trocar um vocábulo por sinônimo aproximado.", 0, "A aula e as bancas (FCC, Cebraspe, Quadrix) cobram equivalência. Sinônimo mal escolhido torce o sentido."),
  qCE(15, "Reescrita", "Se a FCC pede reescrita sem mudar o sentido, qualquer sinônimo de dicionário serve, mesmo que inverta a causa e o efeito do original.", 1, "Equivalência não é troca cega. A aula insiste: a relação entre as ideias tem de continuar a mesma."),
  qCE(16, "Pegadinhas de banca", "A Cebraspe, no certo/errado, frequentemente recorta um trecho verdadeiro e insere um absoluto ('sempre', 'apenas') que o texto não autoriza.", 0, "Pegadinha clássica da aula aplicada à banca: o núcleo está certo; o detalhe absoluto derruba o item."),
  qCE(17, "Pegadinhas de banca", "A FCC jamais cobra reescrita, coesão nem tipologia; suas provas de português restringem-se a ortografia isolada.", 1, "FCC pesa interpretação, equivalência e gramática no texto. A aula de compreensão cai nas três bancas citadas."),
  qCE(18, "Inferência", "Trecho: 'O hospital abriu o terceiro turno, mas a fila das 5h não encolheu.' Infere-se, com segurança, que os médicos recusaram atender de propósito.", 1, "O 'mas' opõe medida e resultado; não acusa intenção. Superinferir dolo é o erro que a aula combate."),
  qCE(19, "De acordo com o texto", "No trecho 'a fila das 5h não encolheu', está explícito que a abertura do terceiro turno não bastou, por si, para reduzir aquela fila.", 0, "Compreensão: o texto diz que a fila não encolheu apesar da medida. Não inventa motivo; registra o fato."),
  qME(20, "De acordo com o texto", "O comando 'de acordo com o texto' pede, em regra, que o candidato:", ["complete lacunas com conhecimento de atualidades", "marque só o que o trecho efetivamente sustenta, sem inventar dado", "ignore conectivos e leia apenas o título", "prefira a alternativa mais 'bonita', ainda que acrescente dado novo"], 1, "Aula: 'de acordo com o texto' prende ao escrito. Atualidades e enfeite não substituem o parágrafo."),
  qCE(21, "Conectivos", "No período 'choveu; logo, o treino foi suspenso', 'logo' introduz conclusão decorrente da informação anterior.", 0, "Na aula, conectivo conclusivo ('logo', 'portanto', 'por isso') fecha raciocínio. Não é oposição."),
  qCE(22, "Conectivos", "'Pois', quando explica causa ('não saiu, pois chovia'), equivale semanticamente a 'contudo' e marca oposição.", 1, "'Pois' explicativo/causal não é adversativo. 'Contudo' e 'porém' é que opõem — troca que a banca adora."),
  qCE(23, "Tipologia", "Texto injuntivo (receita, edital, manual) orienta o leitor a fazer algo; o modo verbal e os verbos de ordem/instrução são marcas típicas.", 0, "A aula de tipologia inclui a injunção ao lado de narração, descrição e dissertação. Edital de concurso é injuntivo."),
  qCE(24, "Tipologia", "A descrição disserta: ao listar a cor das paredes de um fórum, o autor necessariamente defende uma tese jurídica sobre o prédio.", 1, "Descrição pinta características; dissertação argumenta. A aula pede não misturar os tipos."),
  qCE(25, "Detalhe (não/apenas/sempre)", "Se o texto diz que 'alguns servidores aderiram à greve' e o item afirma que 'todos aderiram', o item está errado pelo absoluto 'todos'.", 0, "Detalhe quantificador. A aula e a Cebraspe cobram exatamente essa troca de 'alguns' por 'todos'."),
  qCE(26, "Título e conclusão", "Em prova de compreensão, pular o título economiza tempo e nunca prejudica a identificação do tema.", 1, "Noslen manda usar o título como atalho do assunto. Ignorá-lo é estratégia ruim, sobretudo em dissertação."),
  qCE(27, "Compreensão vs interpretação", "Trecho: 'A ciclovia ficou pronta; o número de acidentes na avenida, porém, cresceu.' Está dito que a ciclovia foi concluída e que os acidentes aumentaram.", 0, "Compreensão: dois fatos explícitos ligados por 'porém'. A oposição está no texto; a causa profunda não."),
  qCE(28, "Inferência", "Do mesmo trecho da ciclovia, conclui-se necessariamente que a ciclovia foi construída com concreto de má qualidade.", 1, "Isso a aula chama de inferência indevida: o 'porém' não aponta o material da obra. Falta base textual."),
  qCE(29, "Reescrita", "A reescrita 'embora a ciclovia tenha ficado pronta, os acidentes cresceram' preserva a oposição do original com 'porém'.", 0, "Concessão/oposição equivalente. A aula de reescrita aceita conectar a mesma relação com outro conectivo adequado."),
  qCE(30, "Reescrita", "Reescrever 'os acidentes cresceram' por 'jamais houve acidente na avenida' mantém o sentido, pois ambas falam de trânsito.", 1, "Há inversão total. Tema parecido não é equivalência — pegadinha de banca que a aula denuncia."),
  qCE(31, "De acordo com o texto", "O comando 'infere-se do texto' autoriza conclusão não literal, desde que o trecho forneça pistas suficientes para sustentá-la.", 0, "Aqui a aula muda o chip: sai da cópia e entra na interpretação. Ainda assim, a pista tem de estar no texto."),
  qCE(32, "Pegadinhas de banca", "Na Quadrix, generalizar o que o autor particularizou é indiferente, porque a banca não cobra fidelidade ao recorte do texto de apoio.", 1, "A aula e a Quadrix cobram recorte fiel. Ampliar 'pode' para 'deve' ou 'hoje' para 'sempre' zera o item."),
  qCE(33, "Conectivos", "Em 'estudou e, ainda assim, foi mal', 'ainda assim' introduz causa, equivalente a 'porque' ou 'pois'.", 1, "É concessivo/adversativo: o resultado desmente a expectativa. A aula pede nomear a relação, não traduzir no piloto automático."),
  qCE(34, "Conectivos", "'Além disso' introduz restrição e anula o que veio antes, funcionando como 'entretanto'.", 1, "'Além disso' é aditivo. 'Entretanto' opõe. Confundir os dois é pegadinha de coesão da aula."),
  qCE(35, "Tipologia", "Um mesmo texto pode combinar tipos: uma reportagem narra um caso, descreve a cena e disserta sobre a política pública.", 0, "A aula admite predominância, não pureza absoluta. O que se cobra é o tipo que manda no conjunto."),
  qCE(36, "Tipologia", "Se há um adjetivo no parágrafo, o texto deixa automaticamente de ser dissertativo e vira só descrição.", 1, "Adjetivo aparece em qualquer tipo. Tipologia se define pela função dominante, não por um vocábulo isolado."),
  qCE(37, "Título e conclusão", "O título 'O apagão da fila única' deve ser ignorado na prova, pois títulos jamais antecipam o eixo temático de um texto dissertativo.", 1, "A aula ensina o contrário: o título é hipótese de leitura, depois checada no corpo e na conclusão."),
  qCE(38, "Detalhe (não/apenas/sempre)", "O item que troca 'quase nunca' do texto por 'nunca' costuma ficar errado, embora as duas formas 'soem' negativas.", 0, "Grau de absoluta. Cebraspe/Quadrix exploram 'quase' vs 'nunca'. A aula pede rigor no detalhe."),
  qCE(39, "Inferência", "Trecho: 'A merenda chegou atrasada três vezes na semana; as famílias protocolaram denúncia.' É lícito inferir que houve insatisfação suficiente para formalizar queixa.", 0, "Inferência curta e ancorada: atraso reiterado + denúncia. A aula aceita esse passo; não aceita inventar desvio de verba."),
  qCE(40, "Inferência", "Do atraso da merenda infere-se, obrigatoriamente, que o nutricionista da rede foi exonerado no mesmo dia.", 1, "Dado inexistente. Interpretação da aula não cria personagem nem sanção que o texto cala."),
  qCE(41, "De acordo com o texto", "Se o autor escreve 'talvez o novo sistema reduza a fila', o item que afirma 'o sistema reduzirá a fila' distorce a modalidade da afirmação.", 0, "Compreensão de modalidade: 'talvez' não é certeza. Banca e aula cobram esse ouvido fino."),
  qCE(42, "Pegadinhas de banca", "Nas bancas Quadrix, Cebraspe e FCC, inserir 'somente' onde o autor não limitou nunca altera o gabarito, porque o núcleo da frase continua verdadeiro.", 1, "Aula aplicada: o recorte verdadeiro ganha um limitador falso e o item cai. O candidato apressado é quem marca 'certo'."),
  qCE(43, "Reescrita", "Passar 'o gestor reconheceu o atraso' para 'foi reconhecido o atraso pelo gestor' pode manter o sentido, mudando apenas a voz verbal.", 0, "Equivalência voz ativa/passiva, desde que agente e fato permaneçam. A aula de reescrita aceita esse tipo de troca."),
  qCE(44, "Reescrita", "Passar 'reconheceu o atraso' para 'negou categoricamente qualquer atraso' é reescrita fiel, porque ambas falam de atraso.", 1, "Polaridade invertida. A aula: tema comum não salva sentido oposto."),
  qCE(45, "Compreensão vs interpretação", "Perguntar 'o que o texto diz?' aponta para compreensão; perguntar 'o que se depreende?' aponta para interpretação.", 0, "Os dois comandos da aula em uma frase. Depreender = inferir, não copiar."),
  qCE(46, "Título e conclusão", "A conclusão com proposta ('é preciso reabrir o diálogo') transforma automaticamente o texto em narração, porque toda proposta é desfecho de conto.", 1, "Proposta é marca dissertativa. A aula liga o fecho à tese; não se lê editorial como desfecho de novela."),
  qCE(47, "Tipologia", "Narração em 1ª pessoa transforma automaticamente o texto em dissertação jurídica, porque todo 'eu' defende tese de direito.", 1, "Memória e conto também usam 1ª pessoa. Pessoa gramatical não define o tipo — a aula olha a função do texto."),
  qME(48, "Tipologia textual", "Predomina a dissertação-argumentativa quando o texto:", ["narra peripécias em ordem cronológica", "descreve um recinto sem opinar", "defende um ponto de vista com argumentos", "lista passos de um formulário"], 2, "Aula de tipologia: dissertação = tese + argumentos. Narração, descrição e injunção são outros eixos."),
  qCE(49, "Conectivos", "Em 'não só ampliou o horário, mas também contratou plantonistas', a correlação soma medidas; não as opõe.", 0, "Adição correlativa. A aula de coesão pede reconhecer 'não só... mas também' como soma, não como 'mas' isolado adversativo."),
  qCE(50, "Detalhe (não/apenas/sempre)", "Leitura de prova: circule no item os termos 'não', 'apenas', 'jamais' e confronte-os com o parágrafo antes de marcar certo ou errado.", 0, "Estratégia final da aula de compreensão: o detalhe é onde a banca esconde o erro. Método, não feeling."),
  qCE(51, "Adjetivo e substantivo", "Na concordância nominal, adjetivo, artigo, pronome e numeral flexionam-se em gênero e número para combinar com o substantivo a que se referem.", 0, "Abertura da aula 01 do Noslen: o núcleo é o substantivo; os modificadores o acompanham."),
  qCE(52, "Adjetivo e substantivo", "O adjetivo permanece invariável em gênero e número, cabendo só ao verbo a tarefa de concordar com o substantivo.", 1, "O contrário da aula: 'as decisões recentes', 'os dois atestados'. Adjetivo concorda sim."),
  qCE(53, "É proibido / é proibida", "Em 'É proibido entrada de animais', 'proibido' fica no masculino singular porque o substantivo veio sem determinante.", 0, "Regra da aula: sem artigo, 'proibido/necessário/preciso/bom/permitido' não flexiona. Com artigo, flexiona."),
  qCE(54, "É proibido / é proibida", "A frase 'É proibida entrada de animais' está de acordo com a norma culta, pois 'entrada' é feminino e o adjetivo deve ir ao feminino mesmo sem artigo.", 1, "Sem artigo, a forma culta é 'É proibido entrada'. 'É proibida a entrada' — aí sim, com artigo."),
  qCE(55, "É proibido / é proibida", "Em 'É proibida a entrada de animais no recinto', a presença do artigo 'a' autoriza a concordância de 'proibida' com 'entrada'.", 0, "Mesma regra da aula, agora no polo determinado: artigo + substantivo → adjetivo concorda."),
  qCE(56, "É necessário", "Está correta a construção 'É necessário a apresentação da certidão negativa', com 'necessário' invariável diante de substantivo determinado.", 1, "Havendo artigo ('a apresentação'), o culto é 'É necessária a apresentação'. Invariável só sem determinante."),
  qCE(57, "É preciso", "A frase 'É preciso cautela na perícia' está adequada: 'cautela' veio sem artigo, e 'preciso' permanece no masculino.", 0, "Espelho de 'é proibido entrada'. Aula 01: locuções predicativas com substantivo nu não flexionam."),
  qCE(58, "É bom", "Em 'São boas as notícias do gabarito', o adjetivo deveria ficar no masculino ('são bons as notícias'), pela regra de 'é bom' invariável.", 1, "Há determinante e núcleo claro: concorda ('boas as notícias'). A invariabilidade vale para 'é bom + substantivo sem artigo'."),
  qCE(59, "Anexo / anexa", "A forma 'Seguem anexas as planilhas de frequência' está correta, pois 'anexas' concorda com 'planilhas'.", 0, "Noslen: 'anexo' é adjetivo. Varia em gênero e número com o que se anexa."),
  qCE(60, "Anexo / anexa", "O ofício 'Encaminho anexo as certidões' está irrepreensível na norma culta, já que 'anexo' nunca flexiona.", 1, "'Anexo' adjetivo flexiona: 'anexas as certidões' ou 'as certidões anexas'. Quem não flexiona é a locução 'em anexo' (aula 02)."),
  qCE(61, "Obrigado / obrigada", "A perita que agradece deve dizer 'Muito obrigada', porque o adjetivo concorda com quem fala, não com quem ouve.", 0, "Aula 01: obrigado/obrigada segue o gênero de quem agradece. Homem: obrigado; mulher: obrigada."),
  qCE(62, "Obrigado / obrigada", "A juíza, ao encerrar o atendimento, deve dizer 'Muito obrigado', pois a forma masculina é a única culta em órgãos públicos.", 1, "Não há forma 'neutra de gabinete'. A magistrada diz 'obrigada'. A aula trata isso como concordância com o falante."),
  qCE(63, "Mesmo / próprio", "Em 'as coordenadoras mesmas redistribuíram as turmas', 'mesmas' concorda com 'coordenadoras'.", 0, "'Mesmo' e 'próprio', como adjetivos/pronomes, flexionam. Aula: ela mesma, eles próprios, as próprias servidoras."),
  qCE(64, "Mesmo / próprio", "A construção 'os diretores mesmo assinaram o ponto' está correta se 'mesmo' funciona como adjetivo com valor de 'eles próprios'.", 1, "Como adjetivo, seria 'os diretores mesmos'. 'Mesmo' invariável só com valor adverbial ('de fato', 'até')."),
  qCE(65, "Próprio", "Está adequada a frase 'Elas próprias protocolaram o recurso no prazo'.", 0, "'Próprias' no feminino plural, de acordo com 'elas'. Item direto da aula de concordância nominal."),
  qCE(66, "Quite", "Depois de quitar o consignado, o servidor pode dizer 'Estou quite com a financeira'.", 0, "Noslen: 'quite' é adjetivo. Singular 'quite'; plural 'quites'. Não é invariável."),
  qCE(67, "Quite", "A frase 'Nós estamos quite com o fisco' está correta, porque 'quite' nunca vai ao plural.", 1, "Dois sujeitos exigem 'quites'. A aula cobra exatamente esse plural esquecido."),
  qCE(68, "Leso", "A expressão culta é 'crime de lesa-pátria', com 'lesa' no feminino em concordância com 'pátria'.", 0, "Aula: 'leso' concorda com o substantivo seguinte. Lesa-pátria, lesa-majestade; leso-patriotismo."),
  qCE(69, "Leso", "Deve-se escrever 'crime de leso-pátria', mantendo o masculino de 'leso' em qualquer combinação.", 1, "Pátria é feminino → lesa-pátria. Congelar no masculino é o erro que a aula aponta."),
  qCE(70, "Um e outro", "Na construção clássica de prova, 'um e outro' puxa o substantivo para o singular: 'um e outro candidato faltou à prova objetiva'.", 0, "Noslen registra: um e outro + núcleo no singular. O adjetivo, em regra, também no singular."),
  qME(71, "É proibido / é proibida", "Assinale a frase em conformidade com a norma culta trabalhada na aula 01:", ["É permitida visitação após as 18h.", "É permitido a visitação após as 18h.", "É permitida a visitação após as 18h.", "É permitidos a visitação após as 18h."], 2, "Com artigo, concorda: 'é permitida a visitação'. Sem artigo, seria 'é permitido visitação'."),
  qCE(72, "Um e outro", "A forma 'um e outro laudos conclusivos' é a única aceita, porque 'um e outro' sempre pluraliza o substantivo.", 1, "O contrário: substantivo no singular ('um e outro laudo conclusivo'). Pluralizar os dois núcleos foge à regra da aula."),
  qCE(73, "Adjetivo depois de dois núcleos", "Em 'estudo e pesquisa aprofundada', o adjetivo pode concordar só com o núcleo mais próximo ('pesquisa').", 0, "Aula: adjetivo posposto a dois substantivos — ou o mais próximo, ou o plural que abranja os dois."),
  qCE(74, "Adjetivo depois de dois núcleos", "Posposto a dois núcleos, o adjetivo não pode ir ao plural: só a concordância com o mais próximo é lícita, jamais 'estudo e pesquisa aprofundados'.", 1, "A aula abre duas portas na posposição: o mais próximo OU o plural abrangente. Proibir o plural é erro."),
  qCE(75, "Adjetivo antes de dois núcleos", "Anteposto, o adjetivo concorda com o mais próximo: 'profunda dor e sofrimento'.", 0, "Aula 01: adjetivo antes de vários substantivos → prioridade ao substantivo imediatamente seguinte."),
  qCE(76, "Adjetivo antes de dois núcleos", "Anteposto a 'casa e terreno', o culto obrigatório é 'antigos casa e terreno', porque o masculino plural prevalece sempre na anteposição.", 1, "Na anteposição, o caminho da aula é o mais próximo: 'antiga casa e terreno'. O plural abrangente é típico da posposição."),
  qCE(77, "Artigo", "Em 'os dois novos códigos', artigo, numeral e adjetivo estão no plural masculino em harmonia com 'códigos'.", 0, "Cadeia completa da aula: tudo que determina o substantivo acompanha gênero e número."),
  qCE(78, "Pronome", "A frase 'aquela duas sentenças' está correta, pois o demonstrativo não precisa acompanhar o numeral.", 1, "Seria 'aquelas duas sentenças'. Pronome demonstrativo concorda. Pegadinha de prova."),
  qCE(79, "Numeral", "Em 'as três primeiras testemunhas', o numeral não participa da concordância nominal, que se limita ao adjetivo.", 1, "A aula inclui o numeral na lista: adjetivo, artigo, pronome e numeral concordam com o substantivo."),
  qCE(80, "É permitido", "Está correta 'É permitido circulação de bicicletas na calçada compartilhada', sem artigo após o predicativo.", 0, "Substantivo sem determinante → 'permitido' invariável. Mesmo esquema de 'é proibido entrada'."),
  qCE(81, "É permitido", "'É permitida circulação de bicicletas' é a forma única culta, independentemente da ausência de artigo.", 1, "Sem artigo, masculino: 'É permitido circulação'. Com artigo: 'É permitida a circulação'."),
  qCE(82, "Anexo / anexa", "'Vão anexos os comprovantes de residência e de escolaridade' concorda com o substantivo masculino plural 'comprovantes'.", 0, "Adjetivo 'anexo' no masculino plural. Aula 01: não congelar em 'anexo' quando o núcleo é plural."),
  qCE(83, "Anexo / anexa", "Em ofício dirigido a juíza, deve-se escrever 'anexo a petição', invariável por cortesia protocolar.", 1, "Cortesia não anula gramática. 'Anexa a petição' ou 'a petição anexa'. A aula não cria exceção de fórum."),
  qCE(84, "Obrigado / obrigada", "O técnico de enfermagem agradece: 'Muito obrigado pelo plantão extra.' A concordância está adequada ao falante masculino.", 0, "Quem fala é homem → obrigado. Não se concorda com 'plantão' nem com a interlocutora."),
  qCE(85, "Mesmo", "Em 'foi o próprio relator quem pediu vista', 'próprio' deveria ir ao feminino ('própria'), porque 'vista' é substantivo feminino.", 1, "'Próprio' concorda com o referente 'relator', não com 'vista'. Aula: próprio/própria seguem de quem se fala."),
  qCE(86, "Quite", "As conselheiras disseram 'estamos quites com a tesouraria'; o plural de 'quite' está adequado.", 0, "'Quites' no plural. A aula trata 'quite' como adjetivo que flexiona em número: quite / quites."),
  qCE(87, "Leso", "Deve-se escrever 'lesa-patriotismo', porque 'leso' fica sempre no feminino por analogia com lesa-pátria.", 1, "A analogia é falsa. A aula manda concordar com o segundo elemento: patriotismo (masc.) → leso-patriotismo."),
  qCE(88, "Um e outro", "Em regra, o adjetivo que qualifica 'um e outro' fica no singular: 'um e outro laudo conclusivo'.", 0, "Aula: um e outro + substantivo singular + adjetivo singular. É o padrão de prova."),
  qCE(89, "Adjetivo e dois núcleos", "Em 'o professor e a professora recém-empossados', o adjetivo no plural masculino pode referir-se aos dois.", 0, "Posposto a núcleos de gêneros diferentes, o plural masculino abrangente é aceito. Aula de adjetivo depois dos substantivos."),
  qCE(90, "Adjetivo e dois núcleos", "A única forma culta seria 'o professor e a professora recém-empossada', sendo ilícito o plural 'empossados'.", 1, "A concordância com o mais próximo ('empossada') é facultativa, não exclusiva. 'Empossados' também cabe."),
  qCE(91, "É necessário", "'Foi necessária a recontagem dos votos da seção' está correta: artigo + substantivo feminino puxam o adjetivo.", 0, "Determinante presente → concorda. Contraste com 'É necessário recontagem' (sem artigo)."),
  qCE(92, "É necessário", "'Foi necessário a recontagem dos votos' é a forma preferida pela norma culta, por analogia com 'é preciso'.", 1, "Com 'a recontagem', o culto é 'foi necessária'. A analogia com 'é preciso' não se aplica a substantivo determinado."),
  qCE(93, "Pronome", "A forma 'todos aquelas relatórios sigilosos' está correta, pois o demonstrativo concorda com 'todos' e não com o substantivo.", 1, "Demonstrativo e adjetivo acompanham o núcleo 'relatórios': 'todos aqueles relatórios sigilosos'."),
  qCE(94, "Anexo / anexa", "'Remeto anexo as certidões' está correta na aula 01, com 'anexo' invariável mesmo diante de núcleo feminino plural.", 1, "'Anexo' adjetivo flexiona: 'anexas as certidões'. Quem não flexiona é 'em anexo', tópico da aula 02."),
  qME(95, "Obrigado / quite / anexo", "Marque a sequência inteiramente adequada à norma da aula 01:", ["Obrigada (homem falando); estamos quite; segue anexo as atas", "Obrigado (homem); estamos quites; seguem anexas as atas", "Obrigada (mulher); estamos quites; segue anexo as atas", "Obrigado (mulher); estamos quite; seguem anexa as atas"], 1, "Falante homem → obrigado; plural → quites; atas femininas → anexas. Três tópicos da aula 01 no mesmo item."),
  qCE(96, "Leso", "Em manchete de concurso, 'ato de lesa-humanidade' concorda no feminino com 'humanidade'.", 0, "Mesmo mecanismo de lesa-pátria. A aula usa 'leso/lesa' como adjetivo preso ao substantivo seguinte."),
  qCE(97, "Adjetivo anteposto", "Anteposto a dois núcleos, o adjetivo deve ir obrigatoriamente ao plural masculino: só 'maus humor e disposição' seria culto.", 1, "Na anteposição, a aula prioriza o mais próximo: 'mau humor e disposição'. O plural abrangente é típico da posposição."),
  qCE(98, "Adjetivo posposto", "'Humor e disposição ruins' é aceitável, com o adjetivo no plural abrangendo os dois núcleos.", 0, "Posposição: plural abrangente. Também caberia 'disposição ruim' (mais próximo). A aula apresenta as duas portas."),
  qCE(99, "Artigo e gênero", "Em 'o guia e a guia turísticos aprovados', o masculino plural é ilícito; só 'turística aprovada' (mais próximo) seria culto.", 1, "Gêneros mistos na posposição admitem o masculino plural abrangente. A via do mais próximo existe, mas não é exclusiva."),
  qCE(100, "Síntese aula 01", "Resumindo a aula 01: o modificador concorda com o substantivo; exceções notáveis são o predicativo sem artigo ('é proibido entrada') e as listas de dois núcleos (mais próximo ou plural).", 0, "Mapa mental do Noslen para a primeira aula de concordância nominal. As peculiares (anexo, obrigado, quite, leso, um e outro) entram nesse quadro."),
  qCE(101, "Bastante adj/adv", "Em 'comprei bastantes pães na padaria da esquina', 'bastantes' é adjetivo e concorda com 'pães'.", 0, "Aula 02: 'bastante' adjetivo (= numerosos) flexiona. 'Bastante' advérbio (= muito) não."),
  qCE(102, "Bastante adj/adv", "A forma 'comprei bastante pães' é a única culta, porque 'bastante' jamais vai ao plural.", 1, "Com substantivo contável no plural, o culto é 'bastantes pães'. A aula usa exatamente esse exemplo-tipo."),
  qCE(103, "Bastante advérbio", "Em 'os plantonistas trabalharam bastante', 'bastante' modifica o verbo e permanece invariável.", 0, "Advérbio. Pluralizar para 'bastantes' aqui seria erro. Noslen opõe os dois empregos na mesma aula."),
  qCE(104, "Bastante advérbio", "'As plantonistas trabalharam bastantes' está correta, pois o advérbio deve ir ao feminino plural com o sujeito.", 1, "Advérbio não concorda com o sujeito. O certo é 'trabalharam bastante'."),
  qCE(105, "Meio adj/adv", "Na frase 'a analista chegou meio receosa', 'meio' é advérbio (= um pouco) e não flexiona.", 0, "Aula 02: 'meio' invariável quando intensifica adjetivo. 'Meia receosa' é o erro clássico."),
  qCE(106, "Meio adj/adv", "'A analista chegou meia receosa' é a forma culta, porque 'receosa' puxa 'meio' para o feminino.", 1, "Não puxa: aí 'meio' não é adjetivo. Só flexiona quando significa 'metade' ('meia hora')."),
  qCE(107, "Meio = metade", "Em 'esperei meia hora no corredor do fórum', 'meia' concorda com 'hora' porque vale 'metade'.", 0, "Adjetivo 'meio/meia'. A aula contrasta com o 'meio' advérbio da frase anterior."),
  qCE(108, "Meio = metade", "Deve-se escrever 'esperei meio hora', invariável, por analogia com 'meio cansada'.", 1, "Analogia falsa. 'Hora' é substantivo feminino + sentido de metade → 'meia hora'."),
  qCE(109, "Meio-dia e meia", "A forma culta é 'a sessão começa ao meio-dia e meia', subentendendo-se 'meia hora'.", 0, "Tópico expresso da aula 02: meio-dia e meia (hora). Não se diz 'meio-dia e meio'."),
  qCE(110, "Meio-dia e meia", "'O edital sai ao meio-dia e meio' está irrepreensível, porque 'dia' é masculino e puxa 'meio'.", 1, "O que se soma ao meio-dia é meia hora, não 'meio dia'. Gabarito de prova: 'meio-dia e meia'."),
  qCE(111, "Caro / barato", "Na norma culta, 'os carros eletrônicos custam caro' traz 'caro' como advérbio de preço, invariável.", 0, "Noslen: custar/sair/sair por + caro/barato = advérbio. Não se diz 'custam caros' nesse valor."),
  qCE(112, "Caro / barato", "'Os carros eletrônicos custam caros' é a forma preferida pela norma culta de concurso, com adjetivo no plural.", 1, "Como preço, invariável: custam caro. 'Caros' caberia em 'carros caros' (adjetivo do substantivo)."),
  qCE(113, "Caro adjetivo", "Em 'compramos bicicletas caras para o batalhão', 'caras' é adjetivo e concorda com 'bicicletas'.", 0, "Agora não é preço verbal, é qualidade do substantivo. Aula: o mesmo vocábulo muda de classe."),
  qCE(114, "Barato advérbio", "'As passagens saíram baratas na promoção' é a única forma culta, porque o verbo 'sair' com ideia de preço exige adjetivo no plural.", 1, "Com preço, a aula manda advérbio invariável: saíram barato. 'Passagens baratas' seria outra estrutura, sem o verbo de preço."),
  qCE(115, "Barato adjetivo", "'Compramos passagens barato para o congresso' está correta se 'barato' for lido como adjetivo de 'passagens'.", 1, "Como adjetivo, seria 'passagens baratas'. 'Barato' invariável só na função adverbial com verbos como custar/sair."),
  qCE(116, "Muito adj/adv", "Em 'as servidoras saíram muito cansadas', 'muito' é advérbio e não flexiona; 'cansadas' é que concorda.", 0, "Aula 02: 'muito' + adjetivo = advérbio invariável. 'Muitas cansadas' seria erro."),
  qCE(117, "Muito adj/adv", "'As servidoras saíram muitas cansadas' é a forma culta, com 'muito' no feminino plural.", 1, "Advérbio não concorda. O adjetivo 'muitas' existiria em 'muitas servidoras' (modificando o substantivo)."),
  qME(118, "Bastante / meio / caro", "Está plenamente culta a seguinte frase:", ["Havia bastante irregularidades; ela ficou meia tensa; os itens custaram caros.", "Havia bastantes irregularidades; ela ficou meio tensa; os itens custaram caro.", "Havia bastantes irregularidades; ela ficou meia tensa; os itens custaram caro.", "Havia bastante irregularidades; ela ficou meio tensa; os itens custaram caros."], 1, "Aula 02 em combo: bastantes (adj.), meio (adv.), custaram caro (adv.)."),
  qCE(119, "Muito adjetivo", "'Havia muitas omissões no relatório de gestão' está correta: 'muitas' adjetivo concorda com 'omissões'.", 0, "Classe diferente da do item anterior. A aula pede classificar antes de flexionar."),
  qCE(120, "Menas", "A forma 'menas' não existe na norma culta; o culto é 'menos', invariável: 'menos reclamações', 'menos filas'.", 0, "Noslen é direto: não existe 'menas'. Pegadinha oral que a banca escreve para o candidato vacilar."),
  qCE(121, "Menas", "'Houve menas contestações no recurso' é aceita em prova, como feminino legítimo de 'menos'.", 1, "Inaceitável. Sempre 'menos', qualquer que seja o gênero do substantivo seguinte."),
  qCE(122, "Em anexo", "A locução 'em anexo' é invariável: 'encaminho em anexo a certidão', 'seguem em anexo os laudos'.", 0, "Aula 02: 'em anexo' funciona adverbialmente e não concorda. Diferente do adjetivo 'anexo/anexa' da aula 01."),
  qCE(123, "Em anexo", "Deve-se escrever 'encaminho em anexa a certidão', flexionando a locução com o substantivo feminino.", 1, "Locução não flexiona. O que flexiona é 'anexa a certidão' (sem 'em')."),
  qCE(124, "Em anexo vs anexo", "Coexistem, cultas, 'segue em anexo a planilha' e 'segue anexa a planilha', com valores adverbial e adjetivo.", 0, "A aula 02 fecha o ciclo aberto na 01: escolha a estrutura e aplique a regra correspondente."),
  qCE(125, "Bastante adjetivo", "'O auditor apontou bastantes falhas no pregão eletrônico' está de acordo com a norma.", 0, "'Falhas' no plural → 'bastantes'. Mesmo raciocínio de 'bastantes pães'."),
  qCE(126, "Bastante adjetivo", "'O auditor apontou bastante falhas no pregão' é preferível, por ser 'bastante' palavra absoluta.", 1, "Com núcleo plural, falta a marca de plural no adjetivo. Erro que a aula treina."),
  qCE(127, "Meio advérbio", "'As ruas ficaram meio desertas depois do toque de recolher' está correta.", 0, "'Meio' = um pouco, invariável, mesmo com feminino plural à direita."),
  qCE(128, "Meio advérbio", "'As ruas ficaram meias desertas' é a concordância obrigatória com 'ruas'.", 1, "Seria adjetivo só se valesse 'metade das ruas desertas', o que a frase não diz. Como intensificador, 'meio'."),
  qCE(129, "Caro advérbio", "'As uniformes do efetivo saíram caro neste semestre' segue a regra de 'custar/sair caro'.", 0, "Advérbio de preço + 'sair'. Não se pluraliza para 'caros' nem se vai a 'caras'."),
  qCE(130, "Caro advérbio", "O culto exige 'as fardas saíram caras neste semestre' quando o verbo for 'sair' com ideia de preço.", 1, "Com preço, a aula manda invariável: saíram caro. 'Fardas caras' seria outra estrutura, sem o verbo de preço."),
  qCE(131, "Barato", "'Achei barato aqueles equipamentos' pode estar culta se 'barato' for advérbio (= por baixo preço).", 0, "Função adverbial, invariável, ainda que 'equipamentos' seja masculino plural. Aula: classifique a função."),
  qCE(132, "Barato", "'Achei baratos aqueles equipamentos' é sempre inculta, porque 'barato' só existe, na aula, como advérbio invariável.", 1, "A leitura adjetiva (predicativo) é culta. A aula 02 não condena o adjetivo; condena misturar as regras."),
  qCE(133, "Muito advérbio", "'Os pareceres vieram muitos bem fundamentados' está culta, com 'muito' no plural para acompanhar 'pareceres'.", 1, "Aí 'muito' é advérbio (modifica 'bem') e não concorda. O culto é 'muito bem fundamentados'."),
  qCE(134, "Muito adjetivo", "'Muitos pareceres vieram fundamentados' está errada, porque 'muito' jamais concorda com substantivo na norma da aula.", 1, "Aqui 'muitos' é adjetivo de 'pareceres' e concorda. A aula pede classificar pela posição e pelo alvo da palavra."),
  qCE(135, "Menas", "Em redação de prova, 'menos alunas faltaram' é a forma correta, ainda que 'alunas' seja feminino.", 0, "'Menos' não tem feminino. A tentação de 'menas alunas' é exatamente o que a aula quer desarmar."),
  qCE(136, "Menas", "'Menas alunas faltaram' deve ser usada para respeitar o gênero de 'alunas' na norma culta.", 1, "Não deve. 'Menas' é marca de desvio. Gabarito: 'menos alunas'."),
  qCE(137, "Em anexo", "'Vão em anexo as guias GRU' está correta, com locução travada no masculino singular aparente.", 0, "Não há flexão 'em anexas'. A invariabilidade é o ponto da aula 02."),
  qCE(138, "Em anexo", "'Vão em anexas as guias GRU' é a concordância obrigatória com 'guias'.", 1, "Hiperconcordância. Ou 'em anexo' (invariável) ou 'anexas as guias' (adjetivo)."),
  qCE(139, "Meio-dia e meia", "'O relógio do plenário marcou meio-dia e meia quando o resultado saiu' está adequada.", 0, "Meia (hora). Tópico isolado que cai muito e a aula destaca com exemplo de relógio."),
  qCE(140, "Meio-dia e meia", "Em linguagem de prova, 'meio-dia e meio' é preferível por concordar com 'dia'.", 1, "Preferível é 'meio-dia e meia'. Concordar com 'dia' é a falsa pista."),
  qME(141, "Menas / em anexo / meio-dia", "A alternativa inteiramente correta é:", ["menas filas; em anexa a ata; meio-dia e meio", "menos filas; em anexo a ata; meio-dia e meia", "menos filas; em anexas a ata; meio-dia e meia", "menas filas; em anexo a ata; meio-dia e meio"], 1, "Três pegadinhas da aula 02: menos invariável, em anexo invariável, meio-dia e meia."),
  qCE(142, "Bastante advérbio vs adjetivo", "'Estudamos bastante' (advérbio) e 'lemos bastantes súmulas' (adjetivo) podem conviver no mesmo parágrafo culto.", 0, "A aula pede reconhecer a função, não memorizar uma forma só. Os dois empregos são legítimos."),
  qCE(143, "Meio adjetivo", "'Usei meios-termos na resposta à impugnação' está correta: 'meio' adjetivo no plural masculino.", 0, "Metade/intermediário → flexiona. 'Meio-termo/meios-termos'. Não confundir com o advérbio."),
  qCE(144, "Meio adjetivo", "'Usei meio-termos na impugnação' é a forma única, porque 'meio' advérbio nunca pluraliza o composto.", 1, "Aqui não é advérbio. O composto adjetivo pluraliza: meios-termos."),
  qCE(145, "Caro", "'Medicamentos caros pesam no orçamento da farmácia pública' — 'caros' adjetivo, plural masculino com 'medicamentos'.", 0, "Sem verbo de preço. Estrutura de qualidade, não de 'custar caro'."),
  qCE(146, "Caro", "'Medicamentos pesam caros no orçamento da farmácia pública' é a forma culta, com adjetivo no plural.", 1, "Com ideia de preço, 'caro' é advérbio: pesam caro. 'Medicamentos caros' seria outra estrutura."),
  qCE(147, "Muito", "'A tese estava muita frágil' é desvio: o intensificador de adjetivo é 'muito', invariável.", 0, "Julga-se o enunciado: a frase citada é desvio, e a afirmação descreve o desvio corretamente. 'Muita' só como adjetivo ('muita fragilidade')."),
  qCE(148, "Muito", "A frase 'a tese estava muita frágil' está culta, com 'muita' no feminino de 'tese'.", 1, "Inculta. 'Muito frágil' (advérbio + adjetivo). 'Muita fragilidade' seria outro recorte."),
  qCE(149, "Síntese aula 02", "O critério da aula 02 é perguntar: a palavra modifica substantivo (adjetivo, concorda) ou verbo/adjetivo/preço (advérbio, não concorda)?", 0, "Bastante, meio, caro, barato, muito — todos passam por esse teste. 'Menas' e 'em anexo' são travas extras."),
  qCE(150, "Síntese aula 02", "Segundo a aula 02, 'bastante', 'meio', 'caro' e 'muito' são sempre advérbios e, portanto, nunca concordam, em qualquer frase.", 1, "São às vezes advérbios, às vezes adjetivos. A generalização 'sempre' é exatamente a pegadinha que a aula desmonta."),
  qCE(151, "TD vs TI", "Verbo transitivo direto rege objeto sem preposição obrigatória ('li o edital'); o indireto exige preposição ('gosto de silêncio').", 0, "Abertura da aula 01 de regência verbal do Noslen: perguntar se o termo vem ou não com preposição."),
  qCE(152, "TD vs TI", "Todo objeto em português vem obrigatoriamente introduzido por preposição; não existe objeto direto na norma culta.", 1, "Existe sim o OD. A aula começa justamente pela oposição TD/TI. Sem isso, esquecer/assistir/visar não se resolvem."),
  qCE(153, "Preposição", "A preposição é o elo típico do objeto indireto; troca-la ou omiti-la altera a regência e, em prova, zera o item.", 0, "Noslen: a preposição não é enfeite. 'Assistir o jogo' vs 'assistir ao jogo' muda o juízo da banca."),
  qCE(154, "Esquecer", "Sem pronome, 'esquecer' é transitivo direto: 'esqueci o protocolo no gabinete'.", 0, "Aula: esquecer algo (TD). Com 'se', a regência muda para 'de'."),
  qCE(155, "Esquecer", "A forma 'esqueci do protocolo' é a única culta, mesmo sem o 'se' apassivador ou pronominal.", 1, "Sem 'se', não cabe 'de'. O culto é 'esqueci o protocolo' ou 'esqueci-me do protocolo'."),
  qCE(156, "Esquecer-se", "'Esqueci-me do prazo de recurso' está correta: verbo pronominal + preposição 'de'.", 0, "Par da aula: esquecer-se de. Os dois caminhos existem; misturá-los é o erro."),
  qCE(157, "Esquecer-se", "'Esqueci-me o prazo de recurso' é a construção culta do verbo pronominal, sem preposição.", 1, "Com 'se', falta o 'de'. 'Esqueci-me de' ou 'esqueci o prazo' (sem se)."),
  qCE(158, "Lembrar", "Paralelo ao esquecer: 'lembrei o número da inscrição' (TD, sem se) está de acordo com a norma.", 0, "Lembrar algo = TD. A aula trata lembrar/esquecer no mesmo bloco."),
  qCE(159, "Lembrar-se", "'Lembrei-me do número da inscrição' está correta, com 'se' + 'de'.", 0, "Lembrar-se de. Mesmo mecanismo do esquecer-se."),
  qCE(160, "Lembrar", "'Lembrei do número' sem 'se' é a forma preferida pela norma culta de concurso.", 1, "É a forma coloquial condenada. Culto: 'lembrei o número' ou 'lembrei-me do número'."),
  qCE(161, "Assistir (TV)", "No sentido de 'ver/presenciar espetáculo', 'assistir' é transitivo indireto: 'assistimos ao debate dos candidatos'.", 0, "Aula: assistir a (programa, jogo, sessão). Em prova, 'assistir o filme' costuma ser dado como erro nesse sentido."),
  qCE(162, "Assistir (TV)", "'Assistimos o debate dos candidatos' é a regência culta no sentido de 'ver o debate na TV'.", 1, "Falta a preposição 'a'. Noslen: quem assiste a algo (espetáculo) não 'assiste algo'."),
  qCE(163, "Assistir (doente)", "No sentido de 'prestar socorro', 'assistir' é transitivo direto: 'a equipe assistiu o acidentado na pista'.", 0, "Segundo emprego da aula: assistir alguém (ajudar). Aqui não se usa 'ao' por obrigação de TI de 'ver'."),
  qCE(164, "Assistir (doente)", "Para 'prestar socorro', a única forma culta é 'assistiu ao acidentado', copiando a regência de 'ver TV'.", 1, "Copiar a preposição de um sentido para o outro é o erro. Socorro = TD; espetáculo = TI + a."),
  qCE(165, "Assistir (caber)", "Em 'não lhe assiste razão', 'assistir' está no sentido de ver TV e deveria ser 'não lhe assiste à razão'.", 1, "Aqui o sentido é 'caber/pertencer' (terceiro emprego da aula), não 'ver espetáculo'. A razão é que assiste a alguém."),
  qCE(166, "Namorar", "Na norma culta ensinada na aula, 'namorar' é transitivo direto: 'ela namora o colega de turma', sem 'em' e sem exigir 'com'.", 0, "Noslen combate 'namorar em' (desvio) e, no padrão de prova, prefere 'namorar alguém' (TD)."),
  qCE(167, "Namorar", "A construção 'ela namora em um militar da PM' está de acordo com a regência culta de 'namorar'.", 1, "'Namorar em' não existe na norma da aula. O objeto é direto: namora um militar / namora o militar."),
  qME(168, "Esquecer / assistir / namorar", "Está correta, segundo a aula 01 de regência:", ["Esqueci do crachá; assisti o seriado; namora em João.", "Esqueci-me do crachá; assisti ao seriado; namora João.", "Esqueci-me o crachá; assisti o seriado; namora com em João.", "Esqueci o crachá; assisti ao seriado; namora em João."], 1, "Esquecer-se de; assistir a (ver); namorar TD. A opção D acerta o esquecer TD, mas peca no 'namora em'."),
  qCE(169, "Visar (objetivo)", "No sentido de 'ter por meta', 'visar' é transitivo indireto: 'o programa visa à redução das filas'.", 0, "Aula: visar a (objetivo). A crase em 'à redução' vem de a (prep.) + a (artigo)."),
  qCE(170, "Visar (objetivo)", "'O programa visa a redução das filas', sem preposição, é a regência culta de 'ter por meta'.", 1, "Como meta, falta o 'a': visa à redução / visa a reduzir. TD caberia noutro sentido (rubricar, mirar)."),
  qCE(171, "Visar (rubrica)", "Em 'o tabelião visou o documento', 'visar' (= apor visto) é transitivo direto.", 0, "Sentido diferente, regência diferente. A aula insiste em não misturar 'objetivo' e 'carimbo'."),
  qCE(172, "Visar (rubrica)", "'O tabelião visou ao documento' é obrigatório, porque 'visar' sempre pede 'a'.", 1, "Nem sempre. Com 'carimbar/rubricar', TD: visou o documento."),
  qCE(173, "Aspirar (inalar)", "No sentido de 'sorver, inalar', 'aspirar' é transitivo direto: 'o operário aspirou o pó da obra'.", 0, "Aula: aspirar algo (fumaça, ar, pó) = TD. Sem preposição."),
  qCE(174, "Aspirar (alvo)", "No sentido de 'pretender, almejar', 'aspirar' pede 'a': 'a servidora aspira ao cargo de analista'.", 0, "Segundo emprego: aspirar a. Espelho de visar (objetivo)."),
  qCE(175, "Aspirar (alvo)", "'A servidora aspira o cargo de analista' está culta no sentido de 'almejar o cargo'.", 1, "Almejar = TI + a. 'Aspirar o cargo' soaria a inalar o cargo — mistura de sentidos da aula."),
  qCE(176, "Implicar (envolver)", "Na acepção de 'acarretar, envolver', a norma culta da aula prefere transitivo direto: 'a medida implica corte de gastos'.", 0, "Noslen (e a prova tradicional): implicar algo, sem 'em'. 'Implicar em' é tratado como desvio."),
  qCE(177, "Implicar (envolver)", "'A medida implica em corte de gastos' é a regência privilegiada pela norma culta de concurso.", 1, "A aula marca 'implicar em' como erro no sentido de acarretar. Prefira 'implica corte'."),
  qCE(178, "Implicar (antipatia)", "Em 'o chefe implicou com o estagiário', 'implicar' (= hostilizar) rege 'com'.", 0, "Terceiro valor: implicar com alguém. Aqui a preposição é outra, e a aula a separa da acepção 'acarretar'."),
  qCE(179, "Pagar", "Paga-se alguma coisa (TD) e paga-se a alguém (TI): 'pagou a multa' / 'pagou ao detran'.", 0, "Bloco pagar/perdoar da aula: coisa = OD; pessoa = OI com 'a'."),
  qCE(180, "Pagar", "'O órgão pagou o fornecedor ontem' é, na linha da aula, a regência culta para a pessoa que recebe.", 1, "Pessoa pede 'a': pagou ao fornecedor. 'Pagar o fornecedor' é o desvio cobrado em prova."),
  qCE(181, "Perdoar", "'A vítima perdoou a dívida, mas não perdoou ao golpista' combina TD (coisa) e TI (pessoa).", 0, "Mesmo esquema de pagar. Perdoar algo / perdoar a alguém. Aula 01 de regência."),
  qCE(182, "Perdoar", "'A vítima perdoou o golpista' é a única forma aceita, sendo ilícito 'perdoar ao golpista'.", 1, "O contrário: a pessoa é OI. 'Perdoar o golpista' é o que a banca costuma considerar errado."),
  qCE(183, "OD preposicionado", "Há objeto direto preposicionado em construções como 'amar a Deus' e 'respeitar aos mais velhos', em que o 'a' não transforma o verbo em TI clássico de 'gostar de'.", 0, "Aula: o OD pode vir com 'a' (pessoa, ênfase, clareza). Não se confunde com o OI obrigatório."),
  qCE(184, "OD preposicionado", "Se o objeto vem com qualquer preposição, trata-se obrigatoriamente de objeto indireto, sem exceção na norma culta.", 1, "A exceção é o OD preposicionado. A aula cita o fenômeno para o candidato não chamar todo 'a' de OI."),
  qCE(185, "Assistir (TV) + crase", "'Assistiremos à sessão solene' está correta: preposição 'a' + artigo 'a' diante de 'sessão'.", 0, "Regência de assistir (ver) + crase. A aula de regência verbal esbarra nesse encontro."),
  qCE(186, "Assistir (TV) + crase", "'Assistiremos a sessão solene', sem crase, é obrigatória, porque 'assistir' nunca se constrói com artigo.", 1, "Há preposição + artigo. A crase é devida. Omiti-la fere a regência de 'assistir a'."),
  qCE(187, "Visar + infinitivo", "'A portaria visa à uniformizar os prazos' é obrigatória, com crase diante de qualquer infinitivo após 'visar'.", 1, "Visar a + infinitivo não tem crase: infinitivo não vem com artigo. A aula de regência costuma acoplar esse detalhe."),
  qCE(188, "Aspirar (inalar)", "'O paciente aspirou ao oxigênio do cilindro' é a forma culta para o sentido de inalar o gás.", 1, "Inalar = TD: aspirou o oxigênio. 'Aspirar a' é almejar. Mais uma mistura de sentidos."),
  qCE(189, "Namorar", "'Há dois anos ela namora o oficial de justiça' está de acordo com a transitividade direta ensinada na aula.", 0, "Sem 'em', sem preposição obrigatória. Contexto de fórum para variar o tema, regra a mesma."),
  qCE(190, "Esquecer / lembrar", "É lícito 'esqueci da senha' e ilícitos tanto 'esqueci a senha' quanto 'esqueci-me da senha', porque o verbo exige sempre a preposição.", 1, "O contrário da aula: os dois padrões (TD sem se / pronominal + de) convivem. O híbrido 'esqueci da' é o que a banca pune."),
  qME(191, "Pagar / perdoar / implicar", "Conforme a aula, a frase culta é:", ["Pagou o perito; perdoou o réu; a regra implica em multa.", "Pagou ao perito; perdoou ao réu; a regra implica multa.", "Pagou ao perito; perdoou o réu; a regra implica em multa.", "Pagou o perito; perdoou ao réu; a regra implica multa."], 1, "Pessoa com 'a'; coisa (multa) como OD de implicar, sem 'em'."),
  qCE(192, "TD vs TI", "Em 'obedecemos às normas do edital', 'obedecer' é transitivo direto, exatamente como 'cumprir as normas', e a preposição é facultativa.", 1, "Obedecer é TI + a. Cumprir é TD. A aula usa pares assim para mostrar que o cenário igual não unifica a regência."),
  qCE(193, "Preposição", "No sentido de almejar, 'aspiramos uma vaga no TJ' (sem preposição) é a forma culta, paralela a 'aspirar o ar'.", 1, "Almejar = aspirar a uma vaga. Sem 'a', mistura-se o sentido de inalar. A aula pune a omissão."),
  qCE(194, "Visar (objetivo)", "'As metas visam o bem-estar dos usuários' está culta no sentido de 'ter por objetivo o bem-estar'.", 1, "Falta 'a': visam ao bem-estar. Item clássico de prova alinhado à aula."),
  qCE(195, "Implicar", "'O atraso implica prejuízo à prova prática' está de acordo com a transitividade direta de 'acarretar'.", 0, "Implica prejuízo (OD). Sem 'em'. Pessoa prejudicada pode aparecer com 'a' ('à prova'), que não é a regência de implicar."),
  qCE(196, "Pagar", "'Paguei o boleto o banco' está culta, porque 'pagar' não admite dois objetos na mesma oração.", 1, "Pagar admite os dois: coisa (OD) e pessoa (OI com a). O modelo da aula é exatamente 'paguei o boleto ao banco'."),
  qCE(197, "Assistir (doente)", "'Os socorristas assistiram os feridos e, à noite, assistiram ao noticiário' explora, corretamente, os dois sentidos e as duas regências.", 0, "TD (socorrer) + TI (ver). A aula vive desse contraste na mesma pessoa do discurso."),
  qCE(198, "OD preposicionado", "Em 'o texto convenceu a todos os presentes', a preposição prova que 'convencer' passou a ser transitivo indireto, no mesmo molde de 'gostar de'.", 1, "É objeto direto preposicionado. A aula cita o fenômeno para o candidato não chamar todo 'a' de OI obrigatório."),
  qCE(199, "Namorar / assistir", "'Namorar no noivo' e 'assistir o telejornal' são, ambos, desvios à luz da aula 01 de regência.", 0, "O enunciado afirma que as duas formas são desvios — e são: namorar (em/no) + assistir TD no sentido de ver. Item certo."),
  qCE(200, "Síntese aula 01", "O método da aula 01 de regência verbal é fixar o sentido do verbo primeiro (ver vs socorrer, inalar vs almejar, coisa vs pessoa) e só então escolher a preposição.", 0, "Mapa final do Noslen: sentido → transitividade → preposição. Sem o primeiro passo, a preposição vira chute."),
];
